  "area.journey.title":"Proje Yolculuğu",
  "area.journey.desc":"Tek bir mission'ın otonom zinciri — ön geliştirme, ekip koordinasyonu, geliştirme, bağımsız inceleme ve teslim — kayıtlarda olduğu gibi. Yalnız okuma; tek eylem Founder'ın pre-dev kararıdır.",
