  "area.executive.title":"Kurucu Yönetim Özeti ve İcra Defteri",
  "area.executive.desc":"Başlık sayıları ile iş koşularının, kaynak sürümlerinin, bağımsız inceleme kararlarının ve teslim durumlarının en yeni önce sıralı defteri — kayıtlarda olduğu gibi. Yalnız okuma; tek eylem Founder'ın pre-dev kararıdır.",
  "executive.eyebrow":"Yönetim Özeti · İcra Defteri · Salt okunur",
  "executive.readonly":"Salt okunur görünüm. Her değer Control API'nin salt okunur GET /v1/cockpit, GET /v1/missions, GET /v1/work-runs ve GET /v1/attention uç noktalarından gelir. Hiçbir ölçü, koşu, karar veya teslim uydurulmaz; bozuk bir yanıt tahmini değer yerine okuma hatası olarak gösterilir.",
  "executive.honesty":"Yalnız kaynak düzeyi. Teslim edilen kaynak paketi, kaynak kodun üretildiği ve kaynak düzeyinde incelendiği anlamına gelir; bu görünüm onu çalışan bir ürün olarak DOĞRULAMAZ. Burada şirket, gelir, müşteri veya erişilebilirlik (uptime) metriği yoktur.",
