  "executive.return.title":"Dönüş Özeti",
  "executive.return.lead":"Bu görünümü bu cihazda son kez görüldü olarak işaretlediğinizden beri koşularda ve mission'larda ne değiştiği. Salt-okunur: aşağıdaki defterle aynı GET /v1/work-runs ve GET /v1/missions okumalarından üretilir; sunucuya hiçbir şey gönderilmez.",
