  "area.queue.title":"İnsan Onayı Bekleyen İş Kuyruğu",
  "area.queue.desc":"İnsan kararı bekleyen her şey — önceliğe göre gruplu ve her öğenin gerçekten ne kadar beklediğiyle. Salt okunur.",
  "queue.eyebrow":"İnsan Onayı Kuyruğu · Öncelik · Bekleme süresi · Salt okunur",
  "queue.readonly":"Salt okunur görünüm. Her öğe Control API'nin salt okunur GET /v1/attention, GET /v1/missions ve GET /v1/work-runs uç noktalarından gelir. Burada hiçbir şey onaylanmaz, reddedilmez veya yeniden denenmez; hiçbir öğe, sayı veya onay uydurulmaz; bozuk bir yanıt tahmini değer olarak değil, okuma hatası olarak gösterilir.",
  "queue.honesty":"Öncelik, öğe türünden türetilen bir görüntü sırasıdır; kontrol düzleminin kaydettiği bir alan değildir. SLA hedefi kayıtlı olmadığı için hiçbiri gösterilmez: bekleme süresi, kayıtlı bir zaman damgasından beri geçen gerçek süredir; bantlar son tarih değil, görüntü gruplamasıdır.",
