  "queue.summary.title":"Kuyruk özeti",
  "queue.summary.lead":"Sayılar yalnız aşağıdaki üç salt-okunur kaynaktan türetilir ve yalnız üçü de okunabildiğinde gösterilir. Bir kaynak okunamıyorsa sayılar — gösterir ve nedeni yazılır, asla sıfır gösterilmez.",
