  "queue.unknownStatus.note":"Mission listesi okunamadı; bu yüzden \"Onay bekleyen koşu, mission durumu bilinmiyor\" olarak listelenen koşuların mission durumu bilinmiyor. Her biri AWAITING_APPROVAL durumunda bir koşudur (koşu listesinden okundu), ancak mission'ının REPORTING durumunda olup olmadığı, yani bir teslim kararı bekleyip beklemediği burada belirlenemez.",
