  "queue.kindDesc.BLOCKED_ITEM":"Sunucu bu koşuyu, mission'ı ya da görevi Founder'a ihtiyaç duyan olarak listeliyor (başarısız ya da engelli koşu, engelli mission veya engelli görev). Burada hiçbir şey değiştirilmez.",
