  "queue.kindDesc.RUN_GATE":"Koşu AWAITING_APPROVAL durumunda ancak mission'ı REPORTING durumunda değil; bu yüzden Gelen Kutusu onun için teslim kararı sunmaz. Durumunu görmek için mission'ı Work'te açın.",
