  "area.readiness.desc":"Her iş koşusu için: bağımsız inceleme kararı, güvenlik taraması, QA testleri, kaynak teslimi ve sunucunun tamamlanma kaydı — ve bir release'in hazır sayılabilmesi için tam olarak nelerin eksik olduğu. Salt okunur.",
  "readiness.eyebrow":"Kalite Kapısı · Release Readiness · Salt okunur",
  "readiness.readonly":"Salt okunur görünüm. Her değer Control API'nin salt okunur GET /v1/work-runs, GET /v1/reviews, GET /v1/cockpit (yalnız kanıt bütünlüğü bloğu) ve GET /v1/missions (yalnız başlıklar) uç noktalarından gelir. Burada hiçbir şey onaylanmaz, reddedilmez, teslim edilmez veya release edilmez; hiçbir kapı, sayı veya karar uydurulmaz; bozuk bir yanıt tahmini değer olarak değil, okuma hatası olarak gösterilir.",
  "readiness.honesty":"Hazırlık yalnız her kapı koşunun güncel head commit'i için gerçekten sağlandığında READY olur. Buradaki teslim yalnız kaynak düzeyindedir: üretilen kod çalıştırılmadığı için NOT_VERIFIED'dır. Verisi okunamayan kapı UNKNOWN'dır, asla geçmiş sayılmaz. Bu görünüm çalışan bir ürünü doğrulamaz.",
