  "readiness.summary.title":"Hazırlık özeti",
  "readiness.summary.lead":"Sayılar yalnız yukarıdaki kaynaklardan türetilir ve yalnız iş koşuları, bağımsız incelemeler ve kanıt bütünlüğü okunabildiğinde gösterilir. Biri okunamıyorsa sayılar — gösterir ve nedeni yazılır, asla sıfır gösterilmez.",
