  "readiness.kpi.q.sourceOnly":"İncelenmiş, güvenlik taramasından geçmiş ve kaynak olarak paketlenmiş; ancak kod çalıştırılmadı ve ürün doğrulanmadı.",
  "readiness.kpi.notReady":"Hazır değil",
  "readiness.kpi.q.notReady":"En az bir kapı henüz sağlanmadı (koşu başına eksikler listelenir).",
  "readiness.kpi.blocked":"Engellendi / reddedildi",
  "readiness.kpi.q.blocked":"Koşu düzeyinde bir kapı olumsuz: koşu başarısız oldu veya durduruldu, inceleyici engelledi, güvenlik taraması engelledi ya da testler başarısız oldu.",
  "readiness.integrity.title":"Platform kanıt bütünlüğü",
  "readiness.integrity.lead":"Platformdaki kayıtlı kanıtların hash doğrulaması (kokpit kanıt bloğundan tam sayımlar). Herhangi bir uyuşmazlık, eksik veya doğrulanamayan kayıt hiçbir koşunun READY olmasına izin vermez.",
  "readiness.integrity.counts":"{total} kanıt kaydının {verified} tanesi hash-doğrulandı · {mismatch} uyuşmazlık · {missing} eksik · {unverifiable} doğrulanamayan.",
