  "area.posture.title":"Güvence Komuta Merkezi ve Güvenlik Duruşu",
  "area.posture.desc":"QA kanıtı, güvenlik taramaları, bağımsız incelemeler ve kanıt bütünlüğünün tek toplu görünümü — ve duruşun güvenceli sayılabilmesi için tam olarak nelerin eksik olduğu. Salt okunur.",
  "posture.eyebrow":"Güvence Komuta Merkezi · Güvenlik Duruşu · Salt okunur",
  "posture.readonly":"Salt okunur görünüm. Her değer Control API'nin salt okunur GET /v1/work-runs, GET /v1/reviews ve GET /v1/cockpit (yalnız kanıt bütünlüğü bloğu) uç noktalarından gelir. Burada hiçbir şey onaylanmaz, reddedilmez, teslim edilmez ya da değiştirilmez.",
  "posture.honesty":"Genel duruş yalnız QA testleri gerçekten yürütüldüğünde, güvenlik taramaları geçtiğinde, bağımsız incelemeler temiz ve bağımsız olduğunda ve her kanıt kaydı hash ile doğrulandığında güvenceli gösterilir. Okunamayan kaynak UNKNOWN'dır; asla sıfır, asla geçmiş sayılmaz. Bu görünüm ürünün doğrulandığını asla iddia etmez.",
