  "posture.summary.title":"Duruş özeti",
  "posture.summary.lead":"Duruş yalnız yukarıdaki kaynaklardan türetilir. Her sayı yalnız bağlı olduğu kaynak okunabildiğinde gösterilir; aksi halde — ve nedeni görünür, asla sıfır değil.",
