  "posture.tierDesc.AT_RISK":"En az bir sütunda olumsuz kanıt var (başarısız ya da engellenmiş test/tarama, reddedilmiş inceleme veya hash uyuşmazlığı). Bu duruşa güvenmeden önce giderin.",
