  "posture.pillars.lead":"Her sütun yalnız kendi kaynağına göre değerlendirilir. Sayılar kayıtlı kanıttan kopyalanır; kaynağı okunamayan sütun sayı göstermez.",
  "posture.pillars.aria":"Duruş sütunları",
  "posture.pillarNote.qa":"Testler yalnız doğrulama ve regresyon testlerinin ikisi de koşunun güncel head'i için tanıklı bir sandbox'ta çalıştığında, 0 ile bittiğinde ve en az bir test yürüttüğünde yürütülmüş sayılır. NOT_EXECUTED asla geçişe çevrilmez.",
  "posture.pillarNote.security":"Yalnız koşunun güncel head'ine bağlı güvenlik taraması sayılır. Başka commit'in taraması STALE'dir; kısmi tarama geçiş değildir; tarama yoksa NOT_EXECUTED'dır.",
  "posture.pillarNote.review":"Bağımsız inceleme durumları sunucudan aynen kopyalanır. Temiz karar yalnız kayıt, inceleyicinin bağımsız olduğunu ve güncel head'i incelediğini doğruladığında sayılır.",
  "posture.pillarNote.integrity":"Platform genelinde kayıtlı kanıtın hash doğrulaması. Herhangi bir uyuşmazlık, eksik ya da doğrulanamayan kayıt veya güncel olmayan kanıt denetimi duruşun güvenceli olmasını engeller.",
