  "area.matrix.title":"Çoklu Proje Komuta Matrisi",
  "area.matrix.desc":"Her proje için tek satır: duruma göre mission ve koşu sayıları, engelli ve onay bekleyen işler, en son kayıtlı inceleme kararı ve yalnız kaynak düzeyinde teslim — önce dikkat gerektiren projeler. Salt okunur.",
  "matrix.eyebrow":"Çoklu Proje Komuta Matrisi · Salt okunur",
  "matrix.readonly":"Salt okunur görünüm. Her değer Control API'nin salt okunur GET /v1/projects, GET /v1/missions, GET /v1/work-runs ve GET /v1/cockpit uç noktalarından gelir. Burada hiçbir şey onaylanmaz, reddedilmez, başlatılmaz, teslim edilmez ya da değiştirilmez.",
  "matrix.honesty":"Bir projenin durumu yalnız kayıtlı etkinliği anlatır — asla sağlıklı ya da doğrulanmış olarak gösterilmez. Bir sayı yalnız bağlı olduğu kaynak okunabildiğinde gösterilir; aksi halde — ve nedeni görünür, asla sıfır değil. İnceleme kararları kaydedildiği gibi görünür. Teslim yalnız kaynak düzeyindedir ve DOĞRULANMADI.",
