  "area.install.desc":"Control API'den okunan dürüst ilk çalıştırma kurulum ve Phase-0 doğrulama durumu: kurulum raporu, Phase-0 kabulü ve AI yürütücüleri. Salt okunur.",
  "install.eyebrow":"İlk çalıştırma kurulum doğrulaması · Salt okunur",
  "install.readonly":"Salt okunur görünüm. Her değer Control API'nin salt okunur GET /v1/install, GET /v1/phase0 ve GET /v1/system/executors uçlarından gelir. Burada hiçbir şey değiştirilemez.",
  "install.honesty":"Doğrulama, sunucunun bildirdiği gibi AYNEN gösterilir (VERIFIED, PENDING veya REJECTED). Okunamayan bir kaynak asla doğrulanmış ya da bağlı gösterilmez, okunamayan bir sayı asla sıfır olarak gösterilmez ve bu ekran üretilmiş hiçbir ürünü doğrulamaz.",
