  "area.audit.title":"Denetim İzi",
  "area.audit.desc":"Son koşuların olay günlüğü yeni-önce tek listede birleştirilir, kanıt referanslarıyla birlikte Control API'den okunur. Salt okunur.",
  "audit.eyebrow":"Denetim İzi · Olaylar · Kanıt · Salt okunur",
  "audit.readonly":"Son {n} koşunun salt-okunur görünümü. Her değer Control API'nin salt-okunur GET /v1/runs, GET /v1/runs/RUN-*/events ve GET /v1/evidence uçlarından gelir. Burada hiçbir şey değiştirilemez.",
  "audit.honesty":"Okunamayan kaynak asla boş ya da temiz liste olarak gösterilmez, okunamayan sayı sıfır olarak gösterilmez ve buradaki hiçbir olay \"onaylandı\", \"sağlıklı\" ya da \"doğrulandı\" anlamına gelmez. Boş liste yalnızca okunabilen kayıtlarda bir şey bulunmadığını söyler.",
  "audit.sources.title":"Veri kaynakları",
  "audit.sources.lead":"Her kaynak bağımsız okunur. \"Okuma başarılı\" yalnızca yanıtın okunabildiği anlamına gelir; bir denetim kararı değildir.",
