  "area.integrations.title":"Uzantılar ve Entegrasyonlar",
  "area.integrations.desc":"Kayıtlı yetenekler, araç adaptörleri ve yürütme fabrikaları, Control API kayıt defterlerinde kayıtlı olduğu gibi gösterilir. Salt okunur; burada hiçbir şey etkinleştirilemez, kurulamaz ya da bağlanamaz.",
  "integrations.eyebrow":"Uzantılar ve Entegrasyonlar · Kayıt defterleri · Salt okunur",
  "integrations.readonly":"Salt okunur görünüm. Her değer Control API'nin salt-okunur GET /v1/capabilities, GET /v1/adapters ve GET /v1/fabrics uçlarından gelir. Etkinleştirme, kurulum ya da bağlama denetimi yoktur.",
  "integrations.honesty":"Durum ve uygulama (implementation) değerleri kayıtlı olduğu gibi gösterilir. REGISTERED yalnızca bir kayıt defterinde girdi bulunduğunu söyler; kurulu, bağlı, etkin, sertifikalı ya da çalışıyor anlamına gelmez, NOT_IMPLEMENTED ise henüz bir uygulama olmadığını söyler. Okunamayan kayıt defteri asla boş gösterilmez ve sayısı sıfır değil tire olarak gösterilir. Etkinleştirme (activation) değeri kayıt defterinde kayıtlı bir politika değeridir, canlı bir durum değildir: öğenin şu anda çalıştığı veya etkin olduğu anlamına gelmez.",
  "integrations.sources.title":"Veri kaynakları",
  "integrations.sources.lead":"Her kayıt defteri bağımsız okunur. \"Okuma başarılı\" yalnızca yanıtın okunabildiği anlamına gelir; hiçbir girdinin çalıştığını söylemez.",
