  "area.operations.title":"Operasyon ve Kurtarma",
  "area.operations.desc":"Kontrol düzlemi durumu, koşu ve kuyruk sağlığı, kurtarma gerektiren paketler ve mevcut durdur / devam et / yeniden dene denetimlerinin dürüst durumu — neyin engelli ya da takılı olduğunu tam olarak listeleyen bir kurtarma kontrol listesiyle. Salt-okunur.",
  "ops.eyebrow":"Operasyon ve Kurtarma · Runbook · Salt-okunur",
  "ops.readonly":"Salt okunur görünüm. Her değer Control API'nin salt okunur GET /v1/control/status, GET /v1/runs ve GET /v1/attention uç noktalarından gelir. Burada hiçbir şey durdurulmaz, sürdürülmez, yeniden denenmez ya da değiştirilmez; mevcut denetimler yerinde kalır.",
  "ops.honesty":"Genel durum yalnız üç kaynak da okunup doğrulandığında, global stop etkin olmadığında, Work OS günlüğü OK iken, en az bir koşu kayıtlıyken, Founder dikkat listesi eksiksizken ve kayıtlı hiçbir şey eylem gerektirmiyorken \"kayıtlı sorun yok\" gösterilir. Okunamayan kaynak BİLİNMİYOR'dur ve asla sorunsuz sayılmaz; takılma yalnız kayıtlı zaman damgalarından ve aşağıdaki görüntü eşiğinden türetilir.",
  "ops.sources.title":"Veri kaynakları",
  "ops.sources.aria":"Veri kaynakları ve okuma durumları",
