  "ops.tierDesc.UNVERIFIED":"Tüm kaynaklar okundu ama gerekli kanıt eksik (örneğin dikkat listesi kesilmiş ya da okunamayan öğeler içeriyor, günlük yok ya da kayıtlı koşu yok), bu yüzden durum doğrulanamıyor.",
  "ops.tierDesc.WATCH":"Hiçbir şey yanlış olarak kayıtlı değil ama bir koşu hâlâ sürüyor. Daha sonra tekrar bakın; bu nihai bir durum değildir.",
  "ops.tierDesc.NO_ISSUES_RECORDED":"Bu ekranda okunan üç Work OS kaynağı da okundu ve doğrulandı, global stop etkin değil, Work OS günlüğü OK, dikkat listesi eksiksiz ve kayıtlı hiçbir durum eylem gerektirmiyor. Bu yalnızca o kaynakları kapsar: eski supervisor'ın yeniden deneme kaydı yalnız Control Tower'da gösterilir, kontrol noktası kaydı bu uygulamada gösterilmez; onlar hakkında hiçbir şey iddia edilmez.",
