  "area.domains.title":"Alan Paketleri",
  "area.domains.desc":"Fabrikaya kayıtlı sektör alan paketleri, Control API kayıt defterinin kaydettiği haliyle gösterilir. Salt-okunur; buradan hiçbir şey etkinleştirilemez.",
  "domains.eyebrow":"Alan Paketleri · Kayıt defteri · Salt-okunur",
  "domains.readonly":"Salt-okunur görünüm. Her değer Control API'nin salt-okunur GET /v1/domains yanıtından gelir. Etkinleştirme, açma ya da kurma denetimi yoktur ve hiçbir şey yazılmaz.",
  "domains.honesty":"Durum (status), etkinleştirme (activation), bilgi durumu ve tazelik değerleri kaydedildiği gibi gösterilir. REGISTERED yalnızca kayıt defterinde bir girdi olduğunu söyler; etkin, güncel, doğrulanmış, uyumlu ya da sertifikalı anlamına gelmez. Tohum (seed) profil doğrulanmış sektör bilgisi değildir ve etkinleştirme değeri kayıtlı bir politika değeridir, canlı bir durum değildir.",
